/* @lc app=leetcode id=1808 lang=kotlin */
class Solution { fun maxNiceDivisors(n: Int): Int = n.toLong().let { nL -> if (nL <= 3) nL.toInt() else (nL % 3).let { r -> java.math.BigInteger.valueOf(3).modPow(java.math.BigInteger.valueOf((if (r == 0L) nL else if (r == 1L) nL - 4 else nL - 2) / 3), java.math.BigInteger.valueOf(1000000007)).multiply(java.math.BigInteger.valueOf(if (r == 0L) 1 else if (r == 1L) 4 else 2)).mod(java.math.BigInteger.valueOf(1000000007)).toInt() } } }